fn factor_address_gate(bad:bool){
 let k:usize=kani::any();let d:usize=kani::any();kani::assume(k<5&&d<5);let f=[cq(),cq(),cq(),cq()];let x=cq();
 let mut w=weights();w.factors[k][d]=f;reset();
