 let i:usize=kani::any();kani::assume(i<4);unsafe{assert_eq!(NCJ_QN,4);assert_eq!(NCJ_QL[i].0,x);assert_eq!(NCJ_QL[i].1,if bad{f[i].add(K::ONE)}else{f[i]});assert_eq!(out[i],NCJ_QL[i].2);}
