 let j:usize=kani::any();kani::assume(j<n);let f=[cq(),cq(),cq(),cq()];reset();
 let x=out[j];
 out[j+0*n]=x.mul(f[0]);out[j+1*n]=x.mul(f[1]);out[j+2*n]=x.mul(f[2]);out[j+3*n]=x.mul(f[3]);
