 let expected=u32::from_le_bytes([bytes[o],bytes[o+1],bytes[o+2],bytes[o+3]]);
 assert!(limbs[k]<2147483647);if bad{assert_ne!(limbs[k],expected);}else{assert_eq!(limbs[k],expected);}
}
